namespace Diaspora.Modules.Community.Contracts.V1.Requests;

/// <summary>An edit to an existing post.</summary>
public sealed record UpdatePostRequest
{
    public required string Body { get; init; }

    public string? Title { get; init; }

    /// <summary>Author-supplied. Never generated by the server from a diff.</summary>
    public string? ChangeSummary { get; init; }

    /// <summary>
    /// A new urgency for a published alert — <c>low</c>, <c>normal</c>, <c>urgent</c> or
    /// <c>emergency</c>. Leave it out to keep the current one. Raising to <c>emergency</c> needs the
    /// same permission as publishing one.
    /// </summary>
    public string? Urgency { get; init; }

    /// <summary>
    /// A new affected radius in metres for a published alert: leave it out to keep the current area,
    /// send <c>0</c> to remove it, or 25 to 50,000 to replace it.
    /// </summary>
    public int? AffectedRadiusMetres { get; init; }

    public IReadOnlyList<AttachmentRequest>? Attachments { get; init; }
}
